<?php
require_once '_bootstrap.php';require_admin_permission('dashboard.view');$db=admin_db();$metrics=[];
foreach(['customers'=>'SELECT COUNT(*) n FROM users','packages'=>"SELECT COUNT(*) n FROM packages WHERE status='published'",'bookings'=>'SELECT COUNT(*) n FROM bookings','pending'=>"SELECT COUNT(*) n FROM bookings WHERE status='pending'",'revenue'=>"SELECT COALESCE(SUM(amount),0) n FROM payments WHERE status IN ('paid','refunded')",'messages'=>"SELECT COUNT(*) n FROM message WHERE status='open'"] as $key=>$sql)$metrics[$key]=$db->query($sql)->fetch_assoc()['n'];
$recent=$db->query('SELECT booking_reference,customer_name,destination,status,total_amount FROM bookings ORDER BY created_at DESC LIMIT 6');$pageTitle='Dashboard';include '_header.php';?>
<div class="page-head"><div><span>India tourism operations</span><h1>Dashboard</h1></div><a class="primary-btn" href="packages.php?action=new"><i class="fa-solid fa-plus"></i>Add package</a></div><section class="metric-grid"><?php foreach([['fa-users','Customers',$metrics['customers']],['fa-map-location-dot','Indian packages',$metrics['packages']],['fa-calendar-check','Bookings',$metrics['bookings']],['fa-clock','Pending',$metrics['pending']],['fa-wallet','Net revenue',inr($metrics['revenue'])],['fa-inbox','Open messages',$metrics['messages']]] as $m):?><article class="metric"><i class="fa-solid <?php echo $m[0];?>"></i><span><?php echo $m[1];?></span><strong><?php echo $m[2];?></strong></article><?php endforeach;?></section><section class="panel"><div class="panel-head"><h2>Recent bookings</h2><a href="bookings.php">View all</a></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Destination</th><th>Status</th><th>Amount (INR)</th></tr></thead><tbody><?php while($b=$recent->fetch_assoc()):?><tr><td><?php echo e($b['booking_reference']?:'-');?></td><td><?php echo e($b['customer_name']);?></td><td><?php echo e($b['destination']);?></td><td><span class="pill"><?php echo e($b['status']);?></span></td><td><?php echo inr($b['total_amount']);?></td></tr><?php endwhile;?></tbody></table></div></section><?php include '_footer.php';?>
